function baselineIndicators(selectedIds = null, unitCode = null) {
  const wanted = selectedIds ? new Set(selectedIds) : null;
  return baselineRows
    .filter(([id]) => !wanted || wanted.has(id))
    .map(([id, titleUa, titleEn, unit, values, noteUa, noteEn]) => {
      const suffix = unitCode ? frameGroupSuffixes[unitCode]?.[id] : null;
      const group = suffix ? `${unitCode.toLowerCase()}-${suffix}` : null;
      const groupTitle = group ? frameGroupTitles[group] : null;
      return makeIndicator({
        id,
        titleUa,
        titleEn,
        unit,
        values: values.map((value, index) => [2021 + index, value]),
        notes: [noteUa, noteEn],
        sourceInfo: sourceWithWorkbook(baselineSourceKeys[id] ?? "statAccounts"),
        forecastFrom: id === "MAC_REAL_INDEX" || id === "MAC_GDP_GROWTH" ? 2026 : null,
        dimensions: {
          ...(group ? { graphGroup: group, graphTitleUa: groupTitle.ua, graphTitleEn: groupTitle.en } : {}),
          sourceSeriesId: id,
        },
      });
    });
}

