function supplementalIndicators(selectedIds, unitCode) {
  return selectedIds.flatMap((id) => {
    const row = supplementalFrameRows[id];
    if (!row) return [];
    const [titleUa, titleEn, unit, values, sourceKey, noteUa, noteEn] = row;
    const suffix = frameGroupSuffixes[unitCode]?.[id];
    const group = suffix ? `${unitCode.toLowerCase()}-${suffix}` : null;
    const groupTitle = group ? frameGroupTitles[group] : null;
    return [makeIndicator({
      id,
      titleUa,
      titleEn,
      unit,
      values,
      notes: [noteUa, noteEn],
      sourceInfo: sourceWithWorkbook(sourceKey),
      dimensions: {
        ...(group ? { graphGroup: group, graphTitleUa: groupTitle.ua, graphTitleEn: groupTitle.en } : {}),
        sourceSeriesId: id,
      },
    })];
  });
}

