function csvEscape(value) { const text = value === null || value === undefined ? "" : String(value); return /[",\n]/u.test(text) ? `"${text.replaceAll('"', '""')}"` : text; }

async function writeDataset(corner, dataset) {
  const folder = resolve(staticRoot, corner, "dataroom", dataset.card.id);
  await mkdir(folder, { recursive: true });
  const rows = dataset.summary.indicators.flatMap((indicator) => indicator.series.map((item) => ({ dataset_id: dataset.card.id, graph_code: indicator.graphCode, indicator_id: indicator.idApi, indicator: indicator.title, period: item.date, value: item.value, unit: indicator.unit, status: item.forecast ? "modelled" : "observed", forecast: item.forecast ? "true" : "false" })));
  const csvHeader = ["dataset_id", "graph_code", "indicator_id", "indicator", "period", "value", "unit", "status", "forecast"];
  const csv = [csvHeader, ...rows.map((row) => csvHeader.map((key) => row[key]))].map((row) => row.map(csvEscape).join(",")).join("\n") + "\n";
  const latestRows = rows.length ? rows.filter((row) => row.period === dataset.summary.latestDate) : dataset.summary.fallbackFacts.map((fact) => ({ ...fact, dataset_id: dataset.card.id }));
  await writeFile(resolve(folder, "summary.json"), `${JSON.stringify(dataset.summary, null, 2)}\n`);
  await writeFile(resolve(folder, "annual.csv"), csv);
  await writeFile(resolve(folder, "latest-001.csv"), rows.length ? csv : "label,period,value,unit,status\n" + dataset.summary.fallbackFacts.map((fact) => [fact.label, fact.period, fact.value, fact.unit, fact.status].map(csvEscape).join(",")).join("\n") + "\n");
  await writeFile(resolve(folder, "latest-001.json"), `${JSON.stringify(latestRows, null, 2)}\n`);
  await writeFile(resolve(folder, "schema.json"), `${JSON.stringify({ datasetId: dataset.card.id, sourceRange: dataset.sourceRange, fields: dataset.summary.schema }, null, 2)}\n`);
  const references = dataset.summary.sourceReferences ?? [source];
  await writeFile(resolve(folder, "sources.json"), `${JSON.stringify(references.map((reference) => ({ ...reference, range: dataset.sourceRange })), null, 2)}\n`);
  await writeFile(resolve(folder, "source.md"), `# Sources\n\n- Workbook range: \`${dataset.sourceRange}\`\n\n${references.map((reference) => `- ${reference.id}: [${reference.label}](${reference.url})${reference.role ? ` (${reference.role})` : ""}`).join("\n")}\n\nThis release preserves workbook values and marks modelled points instead of treating them as observations.\n`);
  await writeFile(resolve(folder, "README.md"), `# ${dataset.card.titleUa}\n\n${dataset.card.descriptionUa}\n\n## English\n\n${dataset.card.descriptionEn}\n\n- Dataset ID: \`${dataset.card.id}\`\n- Graph code: \`${dataset.card.graphCodeBase}\`\n- Source range: \`${dataset.sourceRange}\`\n- Canonical references: ${references.filter((reference) => reference.id !== workbookSource.id).map((reference) => `[${reference.id}](${reference.url})`).join(", ") || "—"}\n`);
}

async function writeCorner(corner, cornerNumber, titleUa, titleEn, descriptionUa, descriptionEn, entries) {
  const cornerRoot = resolve(staticRoot, corner);
  await rm(cornerRoot, { recursive: true, force: true });
  await mkdir(resolve(cornerRoot, "reports"), { recursive: true });
  await writeFile(resolve(cornerRoot, "f1-ukraine.json"), `${JSON.stringify(f1Source, null, 2)}\n`);
  for (const entry of entries) await writeDataset(corner, entry);
  const manifest = { meta: { generatedAt, source: source.label, sourceUrl: source.url, datasetCount: entries.length, liveDatasetCount: entries.length, failedDatasetCount: 0, factOnlyDatasetCount: entries.filter((entry) => !entry.summary.indicators.length).length, regionalDatasetCount: 0, graphReadyDatasetCount: entries.filter((entry) => entry.summary.indicators.length).length, cornerNumber, publisher: source.label, storageModel: "Flat normalized JSON, CSV and Markdown release", coverageReport: { json: `/uc/${corner}/dataroom/coverage-report.json`, markdown: `/uc/${corner}/dataroom/COVERAGE.md` } }, datasets: entries.map((entry) => entry.card), failures: [], factsOnly: entries.filter((entry) => !entry.summary.indicators.length).map((entry) => ({ id: entry.card.id, factsCount: entry.card.fallbackFacts?.length ?? 0 })) };
  manifest.meta.sourceSnapshot = `/uc/${corner}/f1-ukraine.json`;
  const reports = [
    { id: "release", period: "annual", kicker: corner === "frames" ? "Gate 1" : "Gate 2", title: corner === "frames" ? "Foresight frames" : "Scenario envelope", deck: descriptionEn, brief: descriptionEn, generatedAt, lead: null, json: `/uc/${corner}/reports/release.json`, markdown: `/uc/${corner}/reports/release.md`, url: `/corner/${corner}/report/release` },
    { id: "baseline", period: "annual", kicker: "Data note", title: "Baseline and boundaries", deck: "Observed baseline values and modelled boundaries are kept in separate indicators.", brief: "Observed baseline values and modelled boundaries are kept in separate indicators.", generatedAt, lead: null, json: `/uc/${corner}/reports/release.json`, markdown: `/uc/${corner}/reports/release.md`, url: `/corner/${corner}/report/baseline` },
    { id: "notes", period: "annual", kicker: "Release notes", title: "Workbook source", deck: "Workbook ranges, units and model status are preserved for every public dataset.", brief: "Workbook ranges, units and model status are preserved for every public dataset.", generatedAt, lead: null, json: `/uc/${corner}/reports/release.json`, markdown: `/uc/${corner}/reports/release.md`, url: `/corner/${corner}/report/notes` },
  ];
  const reportBody = { corner, cornerNumber, generatedAt, source, datasets: entries.map((entry) => entry.card.id), notes: ["No workbook value was converted into an observed value.", "2026 and 2040 modelled values remain explicitly marked."] };
  await writeFile(resolve(cornerRoot, "dataroom/manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
  await writeFile(resolve(cornerRoot, "reports/manifest.json"), `${JSON.stringify(reports, null, 2)}\n`);
  await writeFile(resolve(cornerRoot, "reports/release.json"), `${JSON.stringify(reportBody, null, 2)}\n`);
  await writeFile(resolve(cornerRoot, "reports/release.md"), `# ${titleUa}\n\n${descriptionUa}\n\n## English\n\n${descriptionEn}\n\nSource: [${source.label}](${source.url})\n`);
  await writeFile(resolve(cornerRoot, "dataroom/COVERAGE.md"), `# ${titleUa} coverage\n\n- Corner: ${cornerNumber}\n- Datasets: ${entries.length}\n- Graph-ready datasets: ${entries.filter((entry) => entry.summary.indicators.length).length}\n- Source: [${source.label}](${source.url})\n\nAll modelled values retain their status; no values are imputed.\n`);
  await writeFile(resolve(cornerRoot, "dataroom/coverage-report.json"), `${JSON.stringify({ generatedAt, corner, cornerNumber, datasetCount: entries.length, source }, null, 2)}\n`);
}

await writeCorner("frames", 15, "Кадри форсайту", "Foresight frames", "Кадр Gate 1: спільна база, шість траєкторій і правила читання сценарної моделі.", "Gate 1: the shared baseline, six trajectories and the reading rules for the scenario model.", framesEntries);
await writeCorner("scenarios", 16, "Сценарії Uconomics", "Uconomics scenarios", "Кадр Gate 2: п’ять канонічних сценаріїв, межі 2040 року та параметри користувацької траєкторії.", "Gate 2: five canonical scenarios, 2040 boundaries and the custom trajectory parameters.", scenarioEntries);

for (const path of [resolve(staticRoot, "universal.json"), resolve(localUniversalRoot, "universal.json")]) {
  const universal = JSON.parse(await readFile(path, "utf8"));
  const additions = [
    { id: "frames", number: 15, name: "FRAMES", title: "Кадри форсайту", titleEn: "Foresight frames", url: "https://ukraine.proto.fund/corner/frames", manifestUrl: "https://ukraine.proto.fund/uc/frames/dataroom/manifest.json", role: "Спільна база та Gate 1", roleEn: "Shared baseline and Gate 1", description: "Спостережувана база і шість траєкторій F1.", descriptionEn: "Observed baseline and six F1 trajectories.", datasetCount: framesEntries.length, deferredCount: 0, observationCount: framesEntries.reduce((sum, entry) => sum + entry.summary.rowCount, 0), coverageStart: "2021-12-31", latestDate: "2040-12-31", categories: [...new Set(framesEntries.map((entry) => entry.card.category))], status: "live" },
    { id: "scenarios", number: 16, name: "SCENARIOS", title: "Сценарії Uconomics", titleEn: "Uconomics scenarios", url: "https://ukraine.proto.fund/corner/scenarios", manifestUrl: "https://ukraine.proto.fund/uc/scenarios/dataroom/manifest.json", role: "Gate 2 та сценарний контракт", roleEn: "Gate 2 and the scenario contract", description: "П’ять канонічних сценаріїв, межі 2040 року та Expert controls.", descriptionEn: "Five canonical scenarios, 2040 boundaries and Expert controls.", datasetCount: scenarioEntries.length, deferredCount: 0, observationCount: scenarioEntries.reduce((sum, entry) => sum + entry.summary.rowCount, 0), coverageStart: "2025-12-31", latestDate: "2040-12-31", categories: [...new Set(scenarioEntries.map((entry) => entry.card.category))], status: "live" },
  ];
  universal.corners = [...universal.corners.filter((corner) => !["frames", "scenarios"].includes(corner.id)), ...additions];
  universal.meta.generatedAt = generatedAt;
  universal.meta.cornerCount = universal.corners.length;
  universal.meta.datasetCount = universal.corners.reduce((sum, corner) => sum + (corner.datasetCount ?? 0), 0);
  universal.meta.observationCount = universal.corners.reduce((sum, corner) => sum + (corner.observationCount ?? 0), 0);
  await writeFile(path, `${JSON.stringify(universal)}\n`);
}

for (const path of [resolve(staticRoot, "id-index.json"), resolve(localUniversalRoot, "id-index.json")]) {
  const index = JSON.parse(await readFile(path, "utf8"));
  for (const [corner, entries] of [["frames", framesEntries], ["scenarios", scenarioEntries]]) {
    for (const entry of entries) {
      const shortId = entry.card.graphCodeBase.replace(/^UA-/u, "").toLocaleLowerCase();
      index.byShortId[shortId] = { shortId, graphCodeBase: entry.card.graphCodeBase, corner, datasetId: entry.card.id, number: entry.card.number, title: entry.card.title, titleUa: entry.card.titleUa, titleEn: entry.card.titleEn, url: `https://ukraine.proto.fund/id/${shortId}` };
    }
  }
  index.generatedAt = generatedAt;
  index.count = Object.keys(index.byShortId).length;
  await writeFile(path, `${JSON.stringify(index, null, 2)}\n`);
}

